'use server'

import { updateTag } from 'next/cache'
import { insertPost } from './lib/posts'

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title) {
    throw new Error('Title is required')
  }

  await insertPost({ title, content })

  // updateTag immediately expires the "posts" tag. Unlike
  // revalidateTag(tag, 'max') (stale-while-revalidate), the next request
  // waits for fresh data instead of serving stale cached content, so the
  // user sees their new post right away (read-your-own-writes).
  updateTag('posts')
}

